<template>
  <div class="demo-page">
    <header>
      <p class="demo-page__eyebrow">远程组件</p>
      <h1 class="demo-page__title">comps-vue3 · RopeGallery</h1>
      <p class="demo-page__lead">
        来自 video-code 的「绳串图片」：一根往下垂的绳子横在画面上方，照片按随机间距挂在绳上，
        每张带一点质量、会被风吹得小幅摆动；抓住任意一张拖动，整根绳子连同所有照片都会跟着偏，
        松手再弹回去。绳子是 canvas 画的二次弧线（垂度 / 横向摆动都是弹簧），照片是绕挂孔旋转的 div，
        每张上面还压一小段「穿绳」和绳子连起来。
      </p>
    </header>

    <section class="rope-demo">
      <div class="rope-demo__head">
        <h2 class="demo-page__section-title">拖动照片 · 整根绳子跟着晃</h2>
        <code class="rope-demo__tag">风 {{ wind.toFixed(1) }}x</code>
      </div>
      <p class="demo-card__text">
        下面的滑杆接的是 <code>v-model:wind</code>：0 基本静止，3 左右是微风，6 会明显晃。
        拖一张照片往任意方向拉，两根绳头固定、中段被拉走的形变会带动所有照片；松手后会回弹。
      </p>

      <div class="rope-demo__toolbar">
        <label class="rope-demo__wind">
          风强度 {{ wind.toFixed(1) }}x
          <input v-model.number="wind" type="range" min="0" max="6" step="0.1" />
        </label>
        <button class="demo-btn demo-btn--ghost" type="button" @click="galleryRef?.shake()">
          重新挂一遍
        </button>
        <span class="rope-demo__count">最近点开：<code>{{ lastSelected }}</code></span>
      </div>

      <div class="rope-demo__stage">
        <RopeGallery
          ref="galleryRef"
          v-model:wind="wind"
          :photos="photos"
          @select="onSelect"
        />
      </div>

      <div class="rope-demo__row">
        <div class="rope-demo__cell">
          <RopeGallery
            :photos="photos.slice(0, 4)"
            :wind="0.4"
            :photo-width="120"
            :photo-height="86"
            :hint="false"
            :draggable="false"
          />
          <p>小尺寸 + 几乎无风 + 不可拖（<code>photoWidth</code> / <code>wind</code> / <code>draggable</code>）</p>
        </div>
        <div class="rope-demo__cell">
          <RopeGallery
            :photos="photos.slice(3)"
            :wind="5.4"
            :photo-width="120"
            :photo-height="86"
            :hint="false"
          />
          <p>大风吹（<code>wind=5.4</code>），照片摆得明显</p>
        </div>
      </div>
    </section>

    <DemoPreview class="rope-preview">
      <LevaPlayground
        name="RopeGallery"
        :component="RopeGallery"
        :schema="RopeGallerySchema"
        :presets="{ photos: photos.slice(0, 5), wind: 3 }"
        :stage-style="stageStyle"
      />
    </DemoPreview>

    <p class="demo-note">
      <span>
        面板里 <code>wind</code> 是风强度（0 ~ 6），<code>photoWidth</code> / <code>photoHeight</code>
        是照片尺寸，<code>inset</code> 是绳子两端留白，<code>draggable</code> 关掉就只摆动不能拖，
        <code>controls</code> 是组件内置的风强度滑杆，<code>hint</code> / <code>hintText</code>
        是底部提示，<code>paused</code> 停掉 rAF。<code>photos</code> 是数组（面板不生成控件）。
      </span>
    </p>
  </div>
</template>

<script setup lang="ts">
import { ref } from 'vue'
import RopeGallerySchema from '@melt-js/comps-vue3/src/components/RopeGallery.propsSchema.json'
import DemoPreview from '../components/DemoPreview.vue'
import LevaPlayground from '../components/LevaPlayground.vue'
import { remoteComponent } from '../configs/remote'

const RopeGallery = remoteComponent('RopeGallery')

type Photo = { src: string; alt: string }

const NAMES = ['山谷', '海边', '旧巷', '雪原', '湖面', '戈壁', '林间']
const PALETTE = [
  ['#6b7f5e', '#2f3e2b'],
  ['#4a7c9b', '#1e3a4d'],
  ['#8a6a4f', '#3d2a1c'],
  ['#9aa7b8', '#3a4553'],
  ['#5f8f8a', '#22403f'],
  ['#b08a5a', '#4a3520'],
  ['#5d7a5a', '#25361f'],
]

/** 生成一张风景底片（渐变 + 远近两层山），不依赖外网 */
function scene(index: number, name: string): string {
  const [top, bottom] = PALETTE[index % PALETTE.length]
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="340" height="240">
    <defs>
      <linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="${top}"/><stop offset="1" stop-color="${bottom}"/>
      </linearGradient>
    </defs>
    <rect width="340" height="240" fill="url(#sky)"/>
    <circle cx="268" cy="58" r="26" fill="#fff" opacity=".35"/>
    <path d="M0 178 L72 128 L138 174 L206 118 L268 168 L340 132 L340 240 L0 240 Z"
      fill="#000" opacity=".28"/>
    <path d="M0 208 L88 168 L170 206 L250 162 L340 200 L340 240 L0 240 Z"
      fill="#000" opacity=".36"/>
    <text x="170" y="222" font-family="'PingFang SC','Microsoft YaHei',sans-serif"
      font-size="17" font-weight="600" fill="rgba(255,255,255,.82)" text-anchor="middle">${name}</text>
  </svg>`
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`
}

const photos: Photo[] = NAMES.map((name, index) => ({
  src: scene(index, name),
  alt: name,
}))

const wind = ref(3)
const lastSelected = ref('（还没点过）')
const galleryRef = ref<{ shake: () => void } | null>(null)

const stageStyle = {
  display: 'block',
  height: '520px',
  padding: '0',
  background: '#f2ede4',
}

function onSelect(index: number) {
  lastSelected.value = `${NAMES[index]}（第 ${index + 1} 张）`
}
</script>

